import { getAdminSession } from "./adminAuth";
import { aborter } from "./aborter";

const BASE_URL =
  process.env.REACT_APP_CASTIA_WORKER_URL ||
  "https://castia-worker.lektodesigns.workers.dev";
const TIMEOUT_MS = 12000;

async function adminFetch(path, { method = "GET", body, signal } = {}) {
  const session = await getAdminSession();
  if (!session?.access_token) {
    const error = new Error("Your admin session has expired. Sign in again.");
    error.status = 401;
    throw error;
  }

  const combined = aborter(TIMEOUT_MS, signal);
  try {
    const response = await fetch(`${BASE_URL}${path}`, {
      method,
      signal: combined.signal,
      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${session.access_token}`,
        ...(body ? { "Content-Type": "application/json" } : {}),
      },
      ...(body ? { body: JSON.stringify(body) } : {}),
    });
    let payload = null;
    try { payload = await response.json(); } catch { /* normalized below */ }
    if (!response.ok) {
      const error = new Error(payload?.error || payload?.message || `Request failed (${response.status})`);
      error.status = response.status;
      error.body = payload;
      throw error;
    }
    return payload;
  } finally {
    combined.cleanup();
  }
}

const requestId = () => crypto.randomUUID();

export const fetchAdminDashboard = (options) => adminFetch("/admin/shop-areas", options);
export const fetchAdminAccess = (options) => adminFetch("/admin/session", options);

export const createShopArea = (values) => adminFetch("/admin/shop-areas", {
  method: "POST",
  body: { requestId: requestId(), ...values },
});

export const updateShopArea = (areaId, values) => adminFetch(`/admin/shop-areas/${areaId}`, {
  method: "PATCH",
  body: { requestId: requestId(), ...values },
});

export const assignWarpArea = (warpId, areaId, warpCategory, reason, expectedUpdatedAt) =>
  adminFetch(`/admin/warp-zones/${warpId}/area`, {
    method: "PUT",
    body: { requestId: requestId(), areaId, warpCategory, reason, expectedUpdatedAt },
  });

export const reviewAreaCandidate = (candidateId, decision, reason, areaName) =>
  adminFetch(`/admin/shop-area-candidates/${candidateId}/${decision}`, {
    method: "POST",
    body: { requestId: requestId(), reason, ...(areaName ? { areaName } : {}) },
  });
