const priorityRank = { classify: 0, high: 1, medium: 2, normal: 3 };

export function buildSurveyQueue(warps = [], hints = []) {
  const needsScan = warps.filter((warp) =>
    warp.status === "needs_scan" && (!warp.warpCategory || warp.warpCategory === "shops"));
  const byId = new Map(warps.map((warp) => [warp.id, warp]));

  return needsScan.map((warp) => {
    const nearby = hints
      .filter((hint) => hint.zoneAId === warp.id || hint.zoneBId === warp.id)
      .map((hint) => {
        const otherId = hint.zoneAId === warp.id ? hint.zoneBId : hint.zoneAId;
        const other = byId.get(otherId);
        return { hint, other, otherSignCount: Number(other?.signCount || 0) };
      })
      .sort((left, right) =>
        right.otherSignCount - left.otherSignCount ||
        Number(left.hint.horizontalDistance || Infinity) - Number(right.hint.horizontalDistance || Infinity));
    const best = nearby[0];
    const evidencedNeighbors = nearby.filter((entry) => entry.otherSignCount > 0).length;
    const priority = !warp.warpCategory ? "classify" : evidencedNeighbors > 0 || nearby.length >= 3 ? "high" : nearby.length > 0 ? "medium" : "normal";
    const why = !warp.warpCategory
      ? "Classify this warp first. Only shop warps need chest-shop surveying."
      : best?.other
      ? best.otherSignCount > 0
        ? `Near /pw ${best.other.warpName}, which already has ${best.otherSignCount} associated sign${best.otherSignCount === 1 ? "" : "s"}.`
        : `Near /pw ${best.other.warpName}; both locations still need sign evidence.`
      : "Known arrival without nearby sign evidence.";

    return {
      ...warp,
      surveyPriority: priority,
      surveyWhy: why,
      nearbyWarpCount: nearby.length,
      evidencedNeighborCount: evidencedNeighbors,
      nearestWarpName: best?.other?.warpName || null,
      nearestWarpDistance: best ? Number(best.hint.horizontalDistance) : null,
    };
  }).sort((left, right) =>
    priorityRank[left.surveyPriority] - priorityRank[right.surveyPriority] ||
    right.evidencedNeighborCount - left.evidencedNeighborCount ||
    (left.nearestWarpDistance ?? Infinity) - (right.nearestWarpDistance ?? Infinity) ||
    left.warpName.localeCompare(right.warpName));
}

export function projectCandidateMap(candidate, width = 640, height = 210, padding = 28) {
  const raw = [
    { id: "warp-a", kind: "warp", zone: "a", x: Number(candidate.zoneACenterX), z: Number(candidate.zoneACenterZ) },
    { id: "warp-b", kind: "warp", zone: "b", x: Number(candidate.zoneBCenterX), z: Number(candidate.zoneBCenterZ) },
    ...(candidate.markers || []).map((marker, index) => ({
      ...marker,
      id: `sign-${index}`,
      kind: "sign",
      zone: marker.warpZoneId === candidate.zoneAId ? "a" : "b",
      x: Number(marker.x),
      z: Number(marker.z),
    })),
  ].filter((point) => Number.isFinite(point.x) && Number.isFinite(point.z));

  if (!raw.length) return { points: [], bounds: null };
  let minX = Math.min(...raw.map((point) => point.x));
  let maxX = Math.max(...raw.map((point) => point.x));
  let minZ = Math.min(...raw.map((point) => point.z));
  let maxZ = Math.max(...raw.map((point) => point.z));
  const expand = (min, max) => {
    const center = (min + max) / 2;
    const span = Math.max(max - min, 32);
    return [center - span / 2, center + span / 2];
  };
  [minX, maxX] = expand(minX, maxX);
  [minZ, maxZ] = expand(minZ, maxZ);
  const usableWidth = Math.max(1, width - padding * 2);
  const usableHeight = Math.max(1, height - padding * 2);

  return {
    bounds: { minX, maxX, minZ, maxZ },
    points: raw.map((point) => ({
      ...point,
      screenX: padding + ((point.x - minX) / (maxX - minX)) * usableWidth,
      screenY: padding + ((point.z - minZ) / (maxZ - minZ)) * usableHeight,
    })),
  };
}
