import { useCallback, useEffect, useMemo, useState } from "react";
import {
  AlertTriangle, CheckCircle2, ClipboardCheck, Layers3,
  Loader2, LogOut, MapPin, RefreshCw, Save, ShieldCheck, Signpost,
} from "lucide-react";
import { toast } from "sonner";
import Header from "@/components/landing/Header";
import Footer from "@/components/landing/Footer";
import SEO from "@/components/ui/SEO";
import { adminAuth, getAdminSession, onAdminAuthChange, sendAdminMagicLink, signOutAdmin } from "@/lib/adminAuth";
import {
  assignWarpArea, createShopArea, fetchAdminDashboard,
  reviewAreaCandidate, updateShopArea,
} from "@/lib/adminClient";
import { buildSurveyQueue, projectCandidateMap } from "@/lib/adminShopAreas";

const fieldClass = "w-full bg-black/20 border border-white/10 rounded-md px-3 py-2 text-sm text-white placeholder:text-zinc-600 focus:outline-none focus:border-emerald-500/60";
const buttonClass = "inline-flex items-center justify-center gap-2 rounded-md px-3 py-2 text-xs font-bold uppercase tracking-wider transition-colors disabled:opacity-40 disabled:pointer-events-none";
const warpCategories = [
  ["", "Unclassified"], ["towns", "Towns"], ["shops", "Shops"],
  ["farms", "Farms"], ["grinders", "Grinders"], ["other", "Other"],
];

function formatDate(value) {
  if (!value) return "Never";
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? "Unknown" : date.toLocaleString();
}

function LoginPanel() {
  const [email, setEmail] = useState("lektodesigns@gmail.com");
  const [sending, setSending] = useState(false);
  const [sent, setSent] = useState(false);

  const submit = async (event) => {
    event.preventDefault();
    setSending(true);
    try {
      await sendAdminMagicLink(email);
      setSent(true);
    } catch (error) {
      toast.error("Could not send sign-in link", { description: error.message });
    } finally {
      setSending(false);
    }
  };

  return <main className="min-h-[78vh] pt-32 pb-24 flex items-center">
    <div className="max-w-md w-full mx-auto px-6">
      <div className="bg-white/[0.025] border border-white/10 rounded-2xl p-7 shadow-2xl">
        <div className="w-11 h-11 rounded-xl bg-emerald-500/10 border border-emerald-500/30 grid place-items-center mb-5">
          <ShieldCheck className="w-5 h-5 text-emerald-400" />
        </div>
        <div className="font-mono text-[10px] uppercase tracking-[0.22em] text-emerald-400 mb-2">Restricted</div>
        <h1 className="font-heading text-3xl font-black tracking-tight mb-3">Area administration</h1>
        <p className="text-sm text-zinc-400 leading-relaxed mb-6">
          Sign in with an approved administrator email. The link expires, and this tab forgets the session when it closes.
        </p>
        {sent ? <div className="rounded-xl border border-emerald-500/30 bg-emerald-500/10 p-4">
          <div className="flex gap-3"><CheckCircle2 className="w-5 h-5 text-emerald-400 shrink-0" />
            <div><div className="text-sm font-semibold">Check your inbox</div>
              <p className="text-xs text-zinc-400 mt-1">Open the link in this browser. You can request another if it expires.</p></div>
          </div>
          <button className={`${buttonClass} border border-white/10 text-zinc-300 mt-4`} onClick={() => setSent(false)}>Use another email</button>
        </div> : <form onSubmit={submit} className="space-y-3">
          <label className="block text-[10px] font-mono uppercase tracking-wider text-zinc-500" htmlFor="admin-email">Admin email</label>
          <input id="admin-email" type="email" autoComplete="email" required value={email} onChange={(event) => setEmail(event.target.value)} className={fieldClass} />
          <button type="submit" disabled={sending} className={`${buttonClass} w-full bg-emerald-500 hover:bg-emerald-400 text-black`}>
            {sending && <Loader2 className="animate-spin" />} Email secure sign-in link
          </button>
        </form>}
      </div>
    </div>
  </main>;
}

function Metric({ label, value, tone = "emerald" }) {
  return <div className="rounded-xl border border-white/10 bg-white/[0.025] p-4">
    <div className={`font-heading text-3xl font-black ${tone === "amber" ? "text-amber-400" : "text-emerald-400"}`}>{value ?? "—"}</div>
    <div className="mt-1 text-[10px] font-mono uppercase tracking-wider text-zinc-500">{label}</div>
  </div>;
}

const commonReviewReasons = {
  approve: [
    "Both warps serve the same physical shop area.",
    "Shared sellers and contiguous sign clusters.",
    "Secondary warp is an entrance to the same shop.",
  ],
  reject: [
    "Separate shops despite nearby warp arrivals.",
    "Different vertical levels or distinct shop layouts.",
    "Evidence does not support combining these warps.",
  ],
};

function CandidateMap({ candidate }) {
  const { points, bounds } = projectCandidateMap(candidate);
  if (!bounds) return null;
  const grid = [0, 1, 2, 3, 4];
  return <div className="rounded-xl overflow-hidden border border-white/[0.08] bg-[#080c10]">
    <div className="flex flex-wrap items-center justify-between gap-2 px-3 py-2 border-b border-white/[0.06] text-[10px] font-mono uppercase tracking-wider text-zinc-500">
      <span>Evidence map · X / Z</span>
      <span className="normal-case tracking-normal">A <i className="inline-block w-2 h-2 rounded-full bg-emerald-400 mx-1" /> B <i className="inline-block w-2 h-2 rounded-full bg-indigo-400 ml-1" /></span>
    </div>
    <svg viewBox="0 0 640 210" role="img" aria-label={`Spatial evidence for ${candidate.zoneAName} and ${candidate.zoneBName}`} className="block w-full h-auto max-h-64">
      <title>Warp arrivals are diamonds; associated chest-shop signs are circles.</title>
      {grid.map((step) => <g key={step}>
        <line x1={28 + step * 146} y1="20" x2={28 + step * 146} y2="190" stroke="#272d35" strokeWidth="1" />
        <line x1="20" y1={28 + step * 38.5} x2="620" y2={28 + step * 38.5} stroke="#272d35" strokeWidth="1" />
      </g>)}
      {points.filter((point) => point.kind === "sign").map((point) => <circle key={point.id} cx={point.screenX} cy={point.screenY} r="4" fill={point.zone === "a" ? "#34d399" : "#818cf8"} fillOpacity="0.8"><title>{point.itemName || "Chest shop"} · {point.x}, {point.y}, {point.z}</title></circle>)}
      {points.filter((point) => point.kind === "warp").map((point) => <g key={point.id} transform={`translate(${point.screenX} ${point.screenY})`}>
        <rect x="-7" y="-7" width="14" height="14" rx="2" transform="rotate(45)" fill={point.zone === "a" ? "#34d399" : "#818cf8"} stroke="#f4f4f5" strokeWidth="2" />
        <text x="0" y="-13" textAnchor="middle" fill="#f4f4f5" fontSize="10" fontWeight="700">{point.zone.toUpperCase()}</text>
      </g>)}
      <text x="26" y="205" fill="#52525b" fontSize="9">X {Math.round(bounds.minX)}–{Math.round(bounds.maxX)} · Z {Math.round(bounds.minZ)}–{Math.round(bounds.maxZ)}</text>
    </svg>
  </div>;
}

function CandidateCard({ candidate, readOnly, busy, onReview }) {
  const [reason, setReason] = useState("");
  const [areaName, setAreaName] = useState(candidate.suggestedAreaName || "");
  const usable = reason.trim().length >= 3;
  const score = Math.round(Number(candidate.score || 0) * 100);
  return <article className="rounded-xl border border-white/10 bg-white/[0.025] p-5">
    <div className="flex flex-wrap items-start justify-between gap-3">
      <div>
        <div className="flex items-center gap-2 font-heading text-lg font-bold">
          /pw {candidate.zoneAName} <span className="text-zinc-600">+</span> /pw {candidate.zoneBName}
        </div>
        <div className="text-xs text-zinc-500 mt-1">{candidate.zoneAOwner || "Unknown owner"} · {candidate.zoneBOwner || "Unknown owner"}</div>
      </div>
      <div className="flex flex-wrap gap-2"><span className="px-2.5 py-1 rounded-full border border-sky-500/30 bg-sky-500/10 text-sky-300 text-[10px] font-mono uppercase tracking-wider">Evidence-backed</span>
        <span className={`px-2.5 py-1 rounded-full border text-[10px] font-mono uppercase tracking-wider ${candidate.recommendation === "strong" ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-300" : "border-amber-500/30 bg-amber-500/10 text-amber-300"}`}>{score}% {candidate.recommendation}</span></div>
    </div>
    <div className="grid grid-cols-2 md:grid-cols-4 gap-2 my-4 text-xs">
      <Signal label="Horizontal" value={`${candidate.horizontalDistance ?? "—"} blocks`} />
      <Signal label="Vertical" value={`${candidate.verticalDistance ?? "—"} blocks`} />
      <Signal label="Signs" value={`${candidate.zoneASignCount} + ${candidate.zoneBSignCount}`} />
      <Signal label="Shared sellers" value={candidate.sharedSellerCount ?? 0} />
    </div>
    <CandidateMap candidate={candidate} />
    <div className="grid grid-cols-2 md:grid-cols-4 gap-2 my-4 text-xs">
      <Signal label="Observations" value={`${candidate.zoneAEvidenceCount} + ${candidate.zoneBEvidenceCount}`} />
      <Signal label="Visits" value={`${candidate.zoneAVisitCount} + ${candidate.zoneBVisitCount}`} />
      <Signal label="Closest signs" value={candidate.clusterHorizontalDistance == null ? "—" : `${candidate.clusterHorizontalDistance} blocks`} />
      <Signal label="Sign Y gap" value={candidate.clusterVerticalDistance == null ? "—" : `${candidate.clusterVerticalDistance} blocks`} />
    </div>
    {!readOnly && <div className="space-y-3">
      <div className="grid md:grid-cols-2 gap-2">
        <input aria-label="Area name" className={fieldClass} value={areaName} onChange={(event) => setAreaName(event.target.value)} placeholder="Area name" />
        <input aria-label="Review reason" className={fieldClass} value={reason} onChange={(event) => setReason(event.target.value)} placeholder="Choose a reason or write a custom note" maxLength={500} />
      </div>
      <div className="grid lg:grid-cols-2 gap-3">
        {Object.entries(commonReviewReasons).map(([decision, reasons]) => <div key={decision}>
          <div className={`mb-1.5 text-[9px] font-mono uppercase tracking-wider ${decision === "approve" ? "text-emerald-400" : "text-red-300"}`}>{decision} reasons</div>
          <div className="flex flex-wrap gap-1.5">{reasons.map((option) => <button key={option} type="button" onClick={() => setReason(option)} className={`rounded-full border px-2.5 py-1 text-[10px] text-left transition-colors ${reason === option ? "border-white/40 bg-white/10 text-white" : "border-white/10 text-zinc-400 hover:border-white/25 hover:text-zinc-200"}`}>{option}</button>)}</div>
        </div>)}
      </div>
      <div className="flex justify-end gap-2">
        <button disabled={!usable || busy || !areaName.trim()} onClick={() => onReview(candidate, "approve", reason, areaName)} className={`${buttonClass} bg-emerald-500 text-black hover:bg-emerald-400`}>Approve</button>
        <button disabled={!usable || busy} onClick={() => onReview(candidate, "reject", reason)} className={`${buttonClass} border border-red-500/30 text-red-300 hover:bg-red-500/10`}>Reject</button>
      </div>
    </div>}
  </article>;
}

function Signal({ label, value }) {
  return <div className="rounded-lg bg-black/20 border border-white/[0.06] px-3 py-2">
    <div className="text-zinc-500 font-mono text-[9px] uppercase tracking-wider">{label}</div>
    <div className="text-zinc-200 mt-0.5">{value}</div>
  </div>;
}

function AreaCard({ area, readOnly, busy, onSave }) {
  const [name, setName] = useState(area.name);
  const [radius, setRadius] = useState(area.assignmentRadius);
  const [vertical, setVertical] = useState(area.verticalTolerance);
  useEffect(() => { setName(area.name); setRadius(area.assignmentRadius); setVertical(area.verticalTolerance); }, [area]);
  const changed = name !== area.name || Number(radius) !== area.assignmentRadius || Number(vertical) !== area.verticalTolerance;
  return <article className="rounded-xl border border-white/10 bg-white/[0.025] p-5">
    <div className="flex items-center justify-between gap-3 mb-4">
      <div><div className="font-heading font-bold text-lg">{area.name}</div><div className="text-xs text-zinc-500">{area.warpCount} warps · {area.signCount} signs</div></div>
      <Layers3 className="w-5 h-5 text-indigo-400" />
    </div>
    <div className="grid md:grid-cols-3 gap-2">
      <label className="text-[10px] font-mono uppercase tracking-wider text-zinc-500">Name<input className={`${fieldClass} mt-1`} value={name} disabled={readOnly} onChange={(e) => setName(e.target.value)} /></label>
      <label className="text-[10px] font-mono uppercase tracking-wider text-zinc-500">Radius<input className={`${fieldClass} mt-1`} type="number" min="8" max="512" value={radius} disabled={readOnly} onChange={(e) => setRadius(e.target.value)} /></label>
      <label className="text-[10px] font-mono uppercase tracking-wider text-zinc-500">Y tolerance<input className={`${fieldClass} mt-1`} type="number" min="4" max="128" value={vertical} disabled={readOnly} onChange={(e) => setVertical(e.target.value)} /></label>
    </div>
    {!readOnly && <button disabled={!changed || busy || !name.trim()} onClick={() => onSave(area, { name, assignmentRadius: Number(radius), verticalTolerance: Number(vertical) })} className={`${buttonClass} mt-3 border border-emerald-500/30 text-emerald-300 hover:bg-emerald-500/10`}><Save /> Save</button>}
  </article>;
}

function WarpRow({ warp, areas, readOnly, busy, onAssign }) {
  const [areaId, setAreaId] = useState(warp.shopAreaId || "");
  const [category, setCategory] = useState(warp.warpCategory || "");
  const [reason, setReason] = useState("");
  useEffect(() => { setAreaId(warp.shopAreaId || ""); setCategory(warp.warpCategory || ""); }, [warp.shopAreaId, warp.warpCategory]);
  const changed = areaId !== (warp.shopAreaId || "") || category !== (warp.warpCategory || "");
  const compatible = areas.filter((area) => area.serverKey === warp.serverKey && area.dimensionKey === warp.dimensionKey);
  return <div className="grid lg:grid-cols-[minmax(190px,1fr)_130px_130px_150px_minmax(180px,1fr)_auto] gap-2 items-center p-3 border-b border-white/[0.06] last:border-0">
    <div><div className="font-mono text-sm text-zinc-200">/pw {warp.warpName}</div><div className="text-[10px] text-zinc-500">{warp.owner || "Unknown owner"} · {warp.centerX}, {warp.centerY}, {warp.centerZ}</div></div>
    <div className="text-xs text-zinc-400">{warp.signCount} signs · {warp.sellerCount} sellers</div>
    <span className={`w-fit text-[9px] uppercase tracking-wider font-mono px-2 py-1 rounded-full border ${warp.status === "assigned" ? "border-emerald-500/20 text-emerald-300" : warp.status === "needs_scan" ? "border-amber-500/20 text-amber-300" : "border-indigo-500/20 text-indigo-300"}`}>{warp.status.replace("_", " ")}</span>
    <select aria-label={`Category for ${warp.warpName}`} className={fieldClass} value={category} disabled={readOnly} onChange={(event) => { const next = event.target.value; setCategory(next); if (next !== "shops") setAreaId(""); }}>
      {warpCategories.map(([value, label]) => <option key={value || "unclassified"} value={value}>{label}</option>)}
    </select>
    <select aria-label={`Area for ${warp.warpName}`} className={fieldClass} value={areaId} disabled={readOnly || category !== "shops"} onChange={(e) => setAreaId(e.target.value)}>
      <option value="">Independent / unassigned</option>
      {compatible.map((area) => <option key={area.id} value={area.id}>{area.name}</option>)}
    </select>
    {!readOnly && <div className="flex gap-2"><input aria-label={`Reason for ${warp.warpName}`} className={`${fieldClass} min-w-36`} value={reason} onChange={(e) => setReason(e.target.value)} placeholder="Optional note" maxLength={500} />
      <button disabled={!changed || busy} onClick={() => onAssign(warp, areaId || null, category || null, reason.trim() || "Manual warp assignment update.")} className={`${buttonClass} bg-emerald-500 text-black`}><Save /></button></div>}
  </div>;
}

function SurveyCategory({ warp, busy, readOnly, onAssign }) {
  const [category, setCategory] = useState(warp.warpCategory || "");
  useEffect(() => setCategory(warp.warpCategory || ""), [warp.warpCategory]);
  if (readOnly) return <div className="text-[10px] text-zinc-500 mt-3">{warp.warpCategory ? `Category: ${warp.warpCategory}` : "Category not set"}</div>;
  return <div className="flex gap-2 mt-3">
    <select aria-label={`Survey category for ${warp.warpName}`} className={fieldClass} value={category} onChange={(event) => setCategory(event.target.value)}>
      {warpCategories.map(([value, label]) => <option key={value || "unclassified"} value={value}>{label}</option>)}
    </select>
    <button disabled={busy || category === (warp.warpCategory || "")} onClick={() => onAssign(warp, category)} className={`${buttonClass} bg-emerald-500 text-black`}><Save /></button>
  </div>;
}

function AdminConsole({ dashboard, loading, busy, onRefresh, onAction, onSignOut }) {
  const [tab, setTab] = useState("queue");
  const [search, setSearch] = useState("");
  const [create, setCreate] = useState({ name: "", serverKey: "play.castiamc.com", dimensionKey: "minecraft:overworld", assignmentRadius: 64, verticalTolerance: 24 });
  const session = dashboard.session || {};
  const readOnly = session.role === "analyst";
  const query = search.trim().toLowerCase();
  const warps = useMemo(() => (dashboard.warps || []).filter((warp) => !query || `${warp.warpName} ${warp.owner} ${warp.shopAreaName}`.toLowerCase().includes(query)), [dashboard.warps, query]);
  const survey = useMemo(() => buildSurveyQueue(warps, dashboard.surveyHints || []), [warps, dashboard.surveyHints]);

  return <main className="pt-28 pb-24 min-h-screen">
    <div className="max-w-7xl mx-auto px-5 md:px-10 lg:px-14">
      <div className="flex flex-wrap justify-between items-end gap-5 mb-8">
        <div><div className="font-mono text-[10px] uppercase tracking-[0.22em] text-emerald-400 mb-2">/ Internal tools</div>
          <h1 className="font-heading text-4xl md:text-6xl font-black tracking-tighter">Shop area <span className="text-emerald-400">control</span></h1>
          <p className="text-sm text-zinc-500 mt-3">Signed in as {session.displayName || "Administrator"} · {session.role}</p></div>
        <div className="flex gap-2">
          <button onClick={onRefresh} disabled={loading} className={`${buttonClass} border border-white/10 text-zinc-300 hover:border-white/30`}><RefreshCw className={loading ? "animate-spin" : ""} /> Refresh</button>
          <button onClick={onSignOut} className={`${buttonClass} border border-red-500/20 text-red-300 hover:bg-red-500/10`}><LogOut /> Sign out</button>
        </div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-6 gap-3 mb-8">
        <Metric label="Warps" value={dashboard.metrics?.totalWarps} />
        <Metric label="Assigned" value={dashboard.metrics?.assignedWarps} />
        <Metric label="With evidence" value={dashboard.metrics?.warpsWithEvidence} />
        <Metric label="Catalog signs" value={dashboard.metrics?.catalogSigns} />
        <Metric label="Unclassified" value={dashboard.metrics?.unclassifiedWarps} tone="amber" />
        <Metric label="Review queue" value={dashboard.metrics?.pendingCandidates} tone="amber" />
      </div>

      {readOnly && <div className="mb-5 rounded-xl border border-indigo-500/30 bg-indigo-500/10 px-4 py-3 text-sm text-indigo-200">Analyst access is read-only.</div>}
      <div className="flex flex-wrap items-center gap-1 border-b border-white/10 mb-6">
        {[["queue", "Review queue", dashboard.candidates?.length], ["areas", "Areas & warps", dashboard.areas?.length], ["survey", "Survey queue", survey.length], ["audit", "Audit log", dashboard.auditEvents?.length]].map(([id, label, count]) =>
          <button key={id} onClick={() => setTab(id)} className={`px-4 py-3 border-b-2 -mb-px text-xs font-mono uppercase tracking-wider ${tab === id ? "border-emerald-400 text-emerald-300" : "border-transparent text-zinc-500 hover:text-white"}`}>{label} <span className="text-zinc-600">{count ?? 0}</span></button>)}
      </div>

      {tab === "queue" && <section className="space-y-3">
        {!dashboard.candidates?.length && <Empty icon={ClipboardCheck} title="Review queue is clear" text="No evidence-based area merge candidates need a decision." />}
        {(dashboard.candidates || []).map((candidate) => <CandidateCard key={candidate.candidateId} candidate={candidate} readOnly={readOnly} busy={busy} onReview={(item, decision, reason, areaName) => onAction(() => reviewAreaCandidate(item.candidateId, decision, reason, areaName), `${decision === "approve" ? "Approved" : "Rejected"} ${item.zoneAName} + ${item.zoneBName}`)} />)}
      </section>}

      {tab === "areas" && <section className="space-y-7">
        {!readOnly && <form className="rounded-xl border border-white/10 bg-white/[0.025] p-5" onSubmit={(e) => { e.preventDefault(); onAction(() => createShopArea(create), `Created ${create.name}`).then((ok) => ok && setCreate((old) => ({ ...old, name: "" }))); }}>
          <h2 className="font-heading text-lg font-bold mb-3">Create an area</h2>
          <div className="grid md:grid-cols-5 gap-2">
            <input required maxLength="80" className={fieldClass} placeholder="Area name" value={create.name} onChange={(e) => setCreate({ ...create, name: e.target.value })} />
            <input required className={fieldClass} placeholder="Server key" value={create.serverKey} onChange={(e) => setCreate({ ...create, serverKey: e.target.value })} />
            <input required className={fieldClass} placeholder="Dimension" value={create.dimensionKey} onChange={(e) => setCreate({ ...create, dimensionKey: e.target.value })} />
            <input type="number" min="8" max="512" className={fieldClass} value={create.assignmentRadius} onChange={(e) => setCreate({ ...create, assignmentRadius: Number(e.target.value) })} />
            <button disabled={busy} className={`${buttonClass} bg-emerald-500 text-black hover:bg-emerald-400`}>Create area</button>
          </div>
        </form>}
        <div className="grid md:grid-cols-2 xl:grid-cols-3 gap-3">{(dashboard.areas || []).map((area) => <AreaCard key={area.id} area={area} readOnly={readOnly} busy={busy} onSave={(item, values) => onAction(() => updateShopArea(item.id, { ...values, expectedUpdatedAt: item.updatedAt }), `Updated ${values.name}`)} />)}</div>
        <div><div className="flex flex-wrap items-center justify-between gap-3 mb-3"><h2 className="font-heading text-xl font-bold">Warp assignments</h2><input className={`${fieldClass} max-w-xs`} placeholder="Filter warp, owner, or area…" value={search} onChange={(e) => setSearch(e.target.value)} /></div>
          <div className="rounded-xl border border-white/10 bg-white/[0.02] overflow-hidden">{warps.map((warp) => <WarpRow key={warp.id} warp={warp} areas={dashboard.areas || []} readOnly={readOnly} busy={busy} onAssign={(item, areaId, category, reason) => onAction(() => assignWarpArea(item.id, areaId, category, reason, item.updatedAt), `Updated /pw ${item.warpName}`)} />)}</div></div>
      </section>}

      {tab === "survey" && <section>
        <div className="flex flex-wrap items-end justify-between gap-3 mb-4"><div><h2 className="font-heading text-xl font-bold">Prioritized field survey</h2><p className="text-sm text-zinc-400 mt-1">Visit the command, allow the mod to record the arrival, then scan nearby chest shops. Proximity is guidance only—not merge evidence.</p></div><input className={`${fieldClass} max-w-xs`} placeholder="Filter warp, owner, or area…" value={search} onChange={(e) => setSearch(e.target.value)} /></div>
        {!survey.length && <Empty icon={Signpost} title="Survey queue is clear" text="Every classified shop warp has sign evidence, and no warp is awaiting classification." />}
        <div className="grid md:grid-cols-2 xl:grid-cols-3 gap-3">{survey.map((warp) => <article key={warp.id} className="rounded-xl border border-white/10 bg-white/[0.025] p-4">
          <div className="flex justify-between gap-3"><div><div className="font-mono text-sm text-amber-300">/pw {warp.warpName}</div><div className="text-xs text-zinc-500 mt-1">{warp.owner || "Unknown owner"}</div></div><span className={`h-fit rounded-full border px-2 py-1 text-[9px] font-mono uppercase tracking-wider ${warp.surveyPriority === "classify" ? "border-sky-500/30 bg-sky-500/10 text-sky-300" : warp.surveyPriority === "high" ? "border-red-500/30 bg-red-500/10 text-red-300" : warp.surveyPriority === "medium" ? "border-amber-500/30 bg-amber-500/10 text-amber-300" : "border-white/10 text-zinc-500"}`}>{warp.surveyPriority}</span></div>
          <div className="mt-4 rounded-lg border border-white/[0.06] bg-black/20 p-3 text-xs text-zinc-300"><div className="mb-1 text-[9px] font-mono uppercase tracking-wider text-zinc-500">Why scan this next</div>{warp.surveyWhy}{warp.nearestWarpDistance != null && <div className="mt-1 text-[10px] text-zinc-500">Arrival distance: {Math.round(warp.nearestWarpDistance)} blocks · {warp.nearbyWarpCount} nearby warp{warp.nearbyWarpCount === 1 ? "" : "s"}</div>}</div>
          <div className="flex items-center gap-2 text-xs text-zinc-400 mt-3"><MapPin className="w-3.5 h-3.5" />{warp.centerX}, {warp.centerY}, {warp.centerZ}</div><div className="text-[10px] text-zinc-600 mt-1">Last observed {formatDate(warp.lastSeenAt)}</div>
          <SurveyCategory warp={warp} busy={busy} readOnly={readOnly} onAssign={(item, category) => onAction(() => assignWarpArea(item.id, category === "shops" ? item.shopAreaId || null : null, category || null, "Warp category classification.", item.updatedAt), `Classified /pw ${item.warpName}`)} />
        </article>)}</div>
      </section>}

      {tab === "audit" && <section className="rounded-xl border border-white/10 bg-white/[0.02] overflow-hidden">
        {!dashboard.auditEvents?.length && <Empty icon={ShieldCheck} title="No changes recorded yet" text="Administrative mutations will appear here with their reason and actor." />}
        {(dashboard.auditEvents || []).map((event) => <div key={event.id} className="p-4 border-b border-white/[0.06] last:border-0 flex flex-wrap gap-3 justify-between">
          <div><div className="font-mono text-xs text-zinc-200">{event.action.replaceAll("_", " ")}</div><div className="text-xs text-zinc-500 mt-1">{event.reason || "No note"}</div></div>
          <div className="text-right text-[10px] text-zinc-600"><div>{event.actorName || event.actorUserId}</div><div>{formatDate(event.createdAt)}</div></div>
        </div>)}
      </section>}
    </div>
  </main>;
}

function Empty({ icon: Icon, title, text }) {
  return <div className="rounded-xl border border-dashed border-white/10 py-14 px-6 text-center"><Icon className="w-7 h-7 text-zinc-600 mx-auto mb-3" /><div className="font-heading font-bold">{title}</div><p className="text-xs text-zinc-500 mt-1">{text}</p></div>;
}

export default function AdminPage() {
  const [session, setSession] = useState(null);
  const [checking, setChecking] = useState(true);
  const [dashboard, setDashboard] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    let mounted = true;
    getAdminSession().then((next) => mounted && setSession(next)).catch(() => {}).finally(() => mounted && setChecking(false));
    const unsubscribe = onAdminAuthChange((next) => { if (mounted) { setSession(next); setChecking(false); } });
    return () => { mounted = false; unsubscribe(); };
  }, []);

  const load = useCallback(async () => {
    if (!session) return;
    setLoading(true); setError(null);
    try { setDashboard(await fetchAdminDashboard()); }
    catch (nextError) { setError(nextError); if (nextError.status === 401) await adminAuth.auth.signOut({ scope: "local" }); }
    finally { setLoading(false); }
  }, [session]);

  useEffect(() => { load(); }, [load]);

  const perform = async (action, success) => {
    setBusy(true);
    try { await action(); toast.success(success); await load(); return true; }
    catch (nextError) { toast.error("Change was not saved", { description: nextError.message }); return false; }
    finally { setBusy(false); }
  };

  return <div data-testid="admin-page" className="min-h-screen bg-bg-base text-white font-body">
    <SEO title="Administration" description="Restricted Castia Market Insight administration." noindex />
    <Header />
    {checking ? <main className="min-h-[78vh] grid place-items-center"><Loader2 className="w-7 h-7 animate-spin text-emerald-400" /></main>
      : !session ? <LoginPanel />
      : error ? <main className="min-h-[78vh] pt-32 px-6"><div className="max-w-lg mx-auto rounded-xl border border-red-500/30 bg-red-500/10 p-6"><AlertTriangle className="text-red-400 mb-3" /><h1 className="font-heading text-2xl font-bold">Admin access unavailable</h1><p className="text-sm text-zinc-400 mt-2">{error.status === 403 ? "This account is signed in but is not on the administrator allowlist." : error.message}</p><div className="flex gap-2 mt-5"><button className={`${buttonClass} bg-emerald-500 text-black`} onClick={load}><RefreshCw /> Retry</button><button className={`${buttonClass} border border-white/10`} onClick={() => signOutAdmin()}><LogOut /> Sign out</button></div></div></main>
      : dashboard ? <AdminConsole dashboard={dashboard} loading={loading} busy={busy} onRefresh={load} onAction={perform} onSignOut={() => signOutAdmin()} />
      : <main className="min-h-[78vh] grid place-items-center"><Loader2 className="w-7 h-7 animate-spin text-emerald-400" /></main>}
    <Footer />
  </div>;
}
